const KG_SOURCE=window.KG_DATA||{directory:[],topicMetrics:{},relations:[],metricInfo:{},meta:{}};
const KG_LEVEL_NAMES={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
const KG_LEVEL_FIELDS={1:'责任中心',2:'业务域',3:'对象',4:'主题'};
function kgUnique(values){return [...new Set(values.filter(Boolean))]}
function kgMetrics(topic){return KG_SOURCE.topicMetrics[topic]||[]}
function kgKey(level,parts){return `${level}:${parts.join('/')}`}
function kgScope(){return state.graphScope||{level:4,parts:['区域TOB','政企','渠道','伙伴激励']}}
function kgScopeActive(level,parts){const scope=kgScope();return scope.level===level&&scope.parts.join('/')===parts.join('/')}
function kgRowsForParts(parts){return KG_SOURCE.directory.filter(row=>parts.every((value,i)=>row[KG_LEVEL_FIELDS[i+1]]===value))}
function kgChildValues(rows,level){return kgUnique(rows.map(row=>row[KG_LEVEL_FIELDS[level]]))}
function kgTreeBranch(label,level,parts,rows,content){const key=kgKey(level,parts),open=state.graphExpanded?.has(key);return `<div class='kg-tree-branch level-${level}'><div class='kg-tree-row ${kgScopeActive(level,parts)?'active':''}'><button class='kg-tree-toggle' type='button' data-kg-toggle='${esc(key)}' aria-label='${open?'收起':'展开'}${esc(label)}' aria-expanded='${open}'>${open?'−':'+'}</button><button class='kg-tree-scope' type='button' data-kg-scope-level='${level}' data-kg-scope-parts='${esc(JSON.stringify(parts))}'><span class='kg-level'>L${level}</span><span class='kg-tree-label'>${esc(label)}</span><small>${level===3?kgChildValues(rows,4).length:rows.length}</small></button></div><div class='kg-tree-children' ${open?'':'hidden'}>${content}</div></div>`}
function kgDirectoryTree(){const rows=KG_SOURCE.directory;return kgChildValues(rows,1).map(l1=>{const r1=rows.filter(x=>x['责任中心']===l1),p1=[l1];const c1=kgChildValues(r1,2).map(l2=>{const r2=r1.filter(x=>x['业务域']===l2),p2=[l1,l2];const c2=kgChildValues(r2,3).map(l3=>{const r3=r2.filter(x=>x['对象']===l3),p3=[l1,l2,l3];const topics=kgChildValues(r3,4).map(topic=>{const p4=[l1,l2,l3,topic];return `<button type='button' class='kg-topic ${kgScopeActive(4,p4)?'active':''}' data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(p4))}'><span class='kg-topic-dot'></span><span>${esc(topic)}</span><small>${kgMetrics(topic).length}</small></button>`}).join('');return kgTreeBranch(l3,3,p3,r3,topics)}).join('');return kgTreeBranch(l2,2,p2,r2,c2)}).join('');return kgTreeBranch(l1,1,p1,r1,c1)}).join('')}
function kgTruncate(name,max=16){return name.length>max?name.slice(0,max-1)+'…':name}
function kgNodeLines(name,max=11){if(name.length<=max)return [name];return [name.slice(0,max-1),kgTruncate(name.slice(max-1),max)]}
function kgScopeMeta(){const scope=kgScope(),rows=kgRowsForParts(scope.parts),label=scope.parts[scope.level-1]||'',topics=kgChildValues(rows,4),topicMetrics=Object.fromEntries(topics.map(topic=>[topic,kgMetrics(topic)])),metrics=kgUnique(Object.values(topicMetrics).flat()),relations=KG_SOURCE.relations.filter(x=>metrics.includes(x.source)||metrics.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!metrics.includes(x)));return {scope,rows,label,topics,topicMetrics,metrics,relations,external,path:scope.parts.join(' / '),type:KG_LEVEL_NAMES[scope.level]}}
function kgMetricNode(name,p,index,external=false){const selected=name===state.selectedGraphMetric,related=KG_SOURCE.relations.some(x=>x.source===name||x.target===name),lines=kgNodeLines(name,10);return `<g class='kg-node ${selected?'selected':''} ${related?'related':''} ${external?'external':''}' style='--i:${index}' role='button' tabindex='0' aria-label='查看指标 ${esc(name)}${external?'，跨主题关联指标':''}' data-metric-node='${esc(name)}' transform='translate(${p.x} ${p.y})'><title>${esc(name)}${external?'（跨主题关联）':''}</title><rect x='-64' y='-21' width='128' height='42' rx='8'/><circle cx='-49' cy='0' r='5'/><text text-anchor='start' x='-38' y='${lines.length===1?4:-3}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-node-sub' text-anchor='start' x='-38' y='11'>${esc(lines[1])}</text>`:''}<text class='kg-node-count' text-anchor='end' x='55' y='4'>${external?'关联':index+1}</text></g>`}
function kgDirectoryNode(label,type,p,index,attrs='',variant='topic'){const lines=kgNodeLines(label,10),interactive=attrs?`role='button' tabindex='0' ${attrs}`:`role='img' aria-label='当前${esc(type)} ${esc(label)}'`;return `<g class='kg-dir-node ${variant}' style='--i:${index}' ${interactive} transform='translate(${p.x} ${p.y})'><rect x='-68' y='-25' width='136' height='50' rx='10'/><text class='kg-dir-type' text-anchor='middle' y='-7'>${type}</text><text class='kg-dir-name' text-anchor='middle' y='${lines.length===1?11:6}'>${esc(lines[0])}</text>${lines[1]?`<text class='kg-dir-name sub' text-anchor='middle' y='18'>${esc(lines[1])}</text>`:''}</g>`}
function kgEdge(path,kind='directory',index=0,arrow=false){return `<path class='kg-edge ${kind}-edge' style='--i:${index}' ${arrow?`marker-end='url(#kg-arrow)'`:''} d='${path}'/>`}
function kgSimpleLevelGraph(meta){const nextLevel=meta.scope.level+1,values=kgChildValues(meta.rows,nextLevel),height=Math.max(430,values.length*82+100),root={x:150,y:height/2};let edges='',nodes='';values.forEach((label,i)=>{const p={x:490,y:70+i*82},parts=[...meta.scope.parts,label],attrs=`data-kg-scope-level='${nextLevel}' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='查看${KG_LEVEL_NAMES[nextLevel]} ${esc(label)}'`;edges+=kgEdge(`M 218 ${root.y} C 310 ${root.y},350 ${p.y},422 ${p.y}`,'directory',i);nodes+=kgDirectoryNode(label,KG_LEVEL_NAMES[nextLevel],p,i,attrs,nextLevel===3?'object':'domain')});return {width:900,height,body:edges+kgDirectoryNode(meta.label,meta.type,root,0,'','root')+nodes,description:`${meta.type}${meta.label}包含 ${values.length} 个${KG_LEVEL_NAMES[nextLevel]}节点。`}}
function kgTopicGraph(meta){const base=kgMetrics(meta.label),relations=KG_SOURCE.relations.filter(x=>base.includes(x.source)||base.includes(x.target)),external=kgUnique(relations.flatMap(x=>[x.source,x.target]).filter(x=>!base.includes(x))),metrics=[...base,...external],cols=metrics.length>18?4:metrics.length>8?3:2,rows=Math.max(1,Math.ceil(metrics.length/cols)),height=Math.max(430,rows*64+100),root={x:110,y:height/2},positions={};metrics.forEach((name,i)=>positions[name]={x:340+(i%cols)*(cols===4?165:220),y:76+Math.floor(i/cols)*64});let edges=base.map((name,i)=>kgEdge(`M 178 ${root.y} C 240 ${root.y},250 ${positions[name].y},276 ${positions[name].y}`,'theme',i)).join('');edges+=relations.map((r,i)=>{const a=positions[r.source],b=positions[r.target];return a&&b?kgEdge(`M ${a.x+64} ${a.y} C ${a.x+95} ${a.y-28},${b.x-95} ${b.y-28},${b.x-64} ${b.y}`,'metric',i,true):''}).join('');const nodes=metrics.map((name,i)=>kgMetricNode(name,positions[name],i,external.includes(name))).join('');return {width:1040,height,body:edges+kgDirectoryNode(meta.label,'主题',root,0,'','root')+nodes,description:`主题${meta.label}包含 ${base.length} 个指标，并显示 ${external.length} 个跨主题关联指标与 ${relations.length} 条指标关系。`}}
function kgObjectGraph(meta){let y=30,index=0,edges='',nodes='',positions={};const topicPositions={};meta.topics.forEach((topic,ti)=>{const metrics=meta.topicMetrics[topic],cols=4,rowCount=Math.max(1,Math.ceil(metrics.length/cols)),groupHeight=Math.max(70,rowCount*54+24),topicY=y+groupHeight/2;topicPositions[topic]={x:280,y:topicY};edges+=kgEdge(`M 158 ROOTY C 200 ROOTY,210 ${topicY},212 ${topicY}`,'directory',ti);const parts=[...meta.scope.parts,topic],attrs=`data-kg-scope-level='4' data-kg-scope-parts='${esc(JSON.stringify(parts))}' aria-label='聚焦主题 ${esc(topic)}'`;nodes+=kgDirectoryNode(topic,'主题',topicPositions[topic],ti,attrs,'topic');metrics.forEach((name,mi)=>{const p={x:470+(mi%cols)*142,y:y+28+Math.floor(mi/cols)*54};positions[name]=p;edges+=kgEdge(`M 348 ${topicY} C 390 ${topicY},400 ${p.y},406 ${p.y}`,'theme',index);nodes+=kgMetricNode(name,p,index++);});y+=groupHeight+14});const height=Math.max(480,y+20),rootY=height/2;edges=edges.replaceAll('ROOTY',String(rootY));meta.relations.forEach((r,i)=>{const a=positions[r.source],b=positions[r.target];if(a&&b)edges+=kgEdge(`M ${a.x+64} ${a.y} C ${a.x+88} ${a.y-24},${b.x-88} ${b.y-24},${b.x-64} ${b.y}`,'metric',i,true)});const root=kgDirectoryNode(meta.label,'对象',{x:90,y:rootY},0,'','root');return {width:1080,height,body:edges+root+nodes,description:`对象${meta.label}包含 ${meta.topics.length} 个主题、${meta.metrics.length} 个指标和 ${meta.relations.length} 条指标关系。`}}
function kgGraphSvg(meta){let graph=meta.scope.level<3?kgSimpleLevelGraph(meta):meta.scope.level===3?kgObjectGraph(meta):kgTopicGraph(meta);return `<svg class='kg-svg dynamic' viewBox='0 0 ${graph.width} ${graph.height}' role='img' aria-labelledby='kg-graph-title kg-graph-desc'><title id='kg-graph-title'>${esc(meta.label)}知识图谱</title><desc id='kg-graph-desc'>${esc(graph.description)}点击目录节点继续钻取，点击指标查看详细信息。</desc><defs><marker id='kg-arrow' viewBox='0 0 10 10' refX='8' refY='5' markerWidth='6' markerHeight='6' orient='auto-start-reverse'><path d='M 0 0 L 10 5 L 0 10 z'/></marker></defs>${graph.body}</svg>`}
function kgValue(value){return value&&String(value).trim()?String(value).trim():'—'}
function kgDetailRows(info){const groups=[['基础信息',['指标来源','指标是否已注册','分析视角']],['分析定义',['分析维度','分析度量','分析方法','下钻路径']],['规则与策略',['指标规则','策略大类','策略子类','策略内容','策略用途']]];return groups.map(([title,fields])=>`<section class='kg-detail-group'><h4>${title}</h4>${fields.map(field=>`<div class='kg-detail-row'><small>${field}</small><p class='${field==='指标规则'||field==='策略内容'?'pre':''}'>${esc(kgValue(info[field]))}</p></div>`).join('')}</section>`).join('')}
function kgDetails(meta){const metric=state.selectedGraphMetric,info=KG_SOURCE.metricInfo[metric]||{};if(!metric)return `<div class='kg-scope-detail'><span>${meta.type}节点</span><b>${esc(meta.label)}</b><p>${esc(meta.path)}</p><dl><div><dt>${meta.topics.length}</dt><dd>主题</dd></div><div><dt>${meta.metrics.length}</dt><dd>指标</dd></div><div><dt>${meta.relations.length}</dt><dd>指标关系</dd></div></dl><small>点击图谱中的目录节点继续钻取，或点击指标查看指标定义。</small></div>`;const links=KG_SOURCE.relations.filter(x=>x.source===metric||x.target===metric);return `<div class='kg-detail-head'><span>指标详情</span><b>${esc(metric)}</b><div><span class='status ${kgValue(info['指标是否已注册'])==='是'?'ok':'warn'}'>${kgValue(info['指标是否已注册'])==='是'?'已注册':'未注册'}</span><span class='kg-rel-count'>${links.length} 条指标关系</span></div></div>${kgDetailRows(info)}${links.length?`<section class='kg-detail-group'><h4>指标关系</h4><div class='kg-related-list'>${links.map(x=>{const incoming=x.target===metric,other=incoming?x.source:x.target;return `<button type='button' data-metric-node='${esc(other)}'><span>${incoming?'上游':'下游'}</span><b>${esc(other)}</b></button>`}).join('')}</div></section>`:''}`}
function kgAdjacency(meta){let rows=[];if(meta.scope.level<3){const next=meta.scope.level+1;kgChildValues(meta.rows,next).forEach(x=>rows.push([meta.type,meta.label,'包含',KG_LEVEL_NAMES[next],x]))}else if(meta.scope.level===3){meta.topics.forEach(topic=>{rows.push(['对象',meta.label,'包含主题','主题',topic]);meta.topicMetrics[topic].forEach(metric=>rows.push(['主题',topic,'包含指标','指标',metric]))});meta.relations.forEach(x=>rows.push(['指标',x.source,'关联指标','指标',x.target]))}else{meta.metrics.forEach(metric=>rows.push(['主题',meta.label,'包含指标','指标',metric]));meta.relations.forEach(x=>rows.push(['指标',x.source,'关联指标','指标',x.target]))}return `<details class='kg-adjacency'><summary><span>关系清单</span><small>无障碍替代视图 · ${rows.length} 条关系</small></summary><div class='table-wrap'><table class='data-table'><thead><tr><th>起点类型</th><th>起点</th><th>关系</th><th>终点类型</th><th>终点</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${esc(x[1])}</td><td>${esc(x[2])}</td><td>${esc(x[3])}</td><td>${x[3]==='指标'?`<button class='kg-table-link' data-metric-node='${esc(x[4])}'>${esc(x[4])}</button>`:esc(x[4])}</td></tr>`).join('')}</tbody></table></div></details>`}
function knowledgeGraphGovernance(stage){const isApproval=stage==='approval',meta=kgScopeMeta();if(!meta.metrics.includes(state.selectedGraphMetric)&&!meta.external.includes(state.selectedGraphMetric))state.selectedGraphMetric='';const action=isApproval?`<button class='btn' data-action='preview-evidence'>查看专家审核记录</button>`:`<button class='btn' data-action='configure-audit-view'>图谱显示设置</button>`;return `${context()}${pageHead(`${isApproval?'STAGE 05 · 领域知识责任人':'STAGE 04 · 领域知识专家'}`,isApproval?'知识审批':'知识审核',isApproval?'按知识目录审阅动态图谱，核对目录、主题、指标定义与关系后提交认证。':'按知识目录逐层浏览动态图谱，核对目录、主题、指标定义与关系。',action)}<section class='kg-summary'><div><span>当前图谱范围 · ${meta.type}</span><b>${esc(meta.path)}</b></div><dl><div><dt>${meta.topics.length}</dt><dd>范围主题</dd></div><div><dt>${meta.metrics.length}</dt><dd>范围指标</dd></div><div><dt>${meta.relations.length}</dt><dd>指标关系</dd></div><div><dt>${KG_SOURCE.meta.uniqueMetrics||0}</dt><dd>全部指标</dd></div></dl></section><div class='kg-workbench'><aside class='panel kg-directory'><div class='panel-head'><div><h3>知识目录</h3><small>L1 责任中心 · L2 业务域 · L3 对象 · L4 主题</small></div></div><div class='kg-directory-body'>${kgDirectoryTree()}</div><footer><span>点击目录名称生成对应图谱</span><small>目录.xlsx · 主题到指标.xlsx</small></footer></aside><section class='panel kg-canvas-panel'><div class='panel-head'><div><h3>${esc(meta.label)}知识图谱</h3><small>${meta.type}节点 · ${meta.topics.length} 个主题 · ${meta.metrics.length} 个指标</small></div><div class='kg-legend'><span><i class='directory'></i>目录节点</span><span><i class='theme'></i>主题</span><span><i class='metric'></i>指标</span><span><i class='relation'></i>指标关系</span></div></div><div class='kg-canvas' tabindex='0' aria-label='${esc(meta.label)}知识图谱画布'>${kgGraphSvg(meta)}</div>${kgAdjacency(meta)}</section><aside class='panel kg-details'><div class='panel-head'><div><h3>节点信息</h3><small>点击目录或指标节点查看</small></div></div><div class='kg-details-body'>${kgDetails(meta)}</div></aside></div>${isApproval?`<section class='panel kg-opinion'><div class='panel-head'><div><h3>审批意见</h3><small>审批意见将写入知识包版本与审计记录</small></div><span class='status ${state.approved?'ok':'warn'}'>${state.approved?'审批通过':'待填写'}</span></div><div class='panel-body'><div class='form-field'><label>领域知识责任人意见</label><textarea placeholder='请输入审批意见'>${state.approved?'审批通过：目录、主题与指标关系准确，可进入认证。':'目录层级清晰，主题与指标关系准确，建议通过审批。'}</textarea></div></div></section>`:''}<div class='action-bar'><span class='notice'>目录实例、主题、指标及指标关系均来自本次提供的 Excel 数据；未配置映射的主题保留空节点。</span><span class='spacer'></span>${isApproval?`<button class='btn danger' data-action='reject-owner'>退回知识专家</button><button class='btn success' data-action='approve-owner'>审批通过并提交认证 →</button>`:`<button class='btn primary' data-action='submit-approval'>审核完成，提交知识审批 →</button>`}</div>`}
function reviewGraphPage(){return knowledgeGraphGovernance('review')}
function approvalGraphPage(){return knowledgeGraphGovernance('approval')}
